TOPICS = [(index, phase, title) for index, phase in enumerate(PHASES) for title in phase["items"] if title != "Project initialization and virtual environment"]
assert len(TASK_SPECS) == len(TOPICS) == 39

REFERENCES = {
    "core": [MODEL, AGENT], "shell": [], "tools": [MODEL, LOCAL],
    "autonomy": [MODEL, ACTIONS, LOCAL, FIXTURE + '/calculator.py', FIXTURE + '/test_calculator.py'],
    "docker": [], "reliability": [ACTIONS, LOCAL, EXCEPTIONS], "memory": [], "security": [DOCKER, LOCAL],
}


def build_tasks():
    result = []
    for number, (spec, topic) in enumerate(zip(TASK_SPECS, TOPICS), start=1):
        key, module, symbols, contract, example, expected = spec
        symbols = task_symbols(spec)
        contract, example, expected = (rewrite_copy(text) for text in (contract, example, expected))
        _, topic_data, title = topic
        target = TASK_PATHS[key]
        lesson = rewrite_copy(topic_data['lesson'])
        if '### Initialize a project you can reproduce' in lesson:
            before, rest = lesson.split('### Initialize a project you can reproduce', 1)
            lesson = before + '### Start in a ready workspace\nNudge supplies the project files, runtime and dependency setup. Start directly with the agent behavior; you do not need to create a virtual environment or write setup code.\n\n### State belongs to the agent' + rest.split('### State belongs to the agent', 1)[1]
        result.append(TaskItem(
            id="mini-swe-build-" + key, order=number, title=title,
            category="security" if module in {"security", "docker"} else "architecture",
            objective=contract.split('. ')[0] + '.', target_file=target,
            task_files=[TaskFile(path=target, purpose="edit"), TaskFile(path=GUIDE, purpose="reference"), *[TaskFile(path=path, purpose="reference") for path in REFERENCES[module] if path != target]],
            estimated_time="20–45 minutes",
            instructions=f"### Your task\n{title}\n\n### Start here\nOpen `{target}` and implement " + ", ".join(f"`{symbol}`" for symbol in symbols) + f". Replace only those placeholders; later tasks implement the remaining helpers.\n\n### Behavior contract\n{contract}\n\n### Example\n```python\n{example}\n```\n\n**Expected result:** {expected}\n\n### Check your work\nSave and choose **Check task**. Checks isolate dependencies that belong to later tasks. Open **Learn the concept** for the explanation before coding.",
            validation_criteria=[f"{title}: expected behavior and output", f"{title}: failure cases and state isolation"],
            hints=[f"Start with the named interface in {target}. Trace the worked example on the concept page.", contract, f"Check the exact return shape, error type and side effects. Expected example: {expected}"],
            mentor_context=f"Teach this single task, not the entire module. Targets: {', '.join(symbols)}. Contract: {contract} Use plain language and small examples. Never suggest exposing provider keys or a Docker socket to the hosted runner.",
            concept_markdown=f"### The concept behind this task\n{title} is one component of the coding agent. Work on this component before connecting the next one.\n\n### Follow a concrete example\n```python\n{example}\n```\n\n**What to expect:** {expected}\n\n### What your component guarantees\n{contract}\n\n### Understand the surrounding mechanism\n{lesson}\n\n### Apply it yourself\nReturn to `{target}` and trace a successful call and a failure case. Which data is copied, which state changes, and which operation must never happen after validation fails? Explain those boundaries before choosing **Check task**.",
        ))
    return result
